'use client';

import { Button as ButtonPrimitive } from '@base-ui/react/button';
import { cva, type VariantProps } from 'class-variance-authority';
import React, { type ElementType } from 'react';

import { useGroup } from '@/components/ui/group';
import { Spinner } from '@/components/ui/spinner';
import { Slot } from '@/registry/base-nova/protoform/lib/base-ui-compat';
import { cn, type SharedProps } from '@/registry/base-nova/protoform/lib/utils';

const buttonVariants = cva(
  [
    'group/button inline-flex shrink-0 items-center justify-center',
    'rounded-lg border border-transparent bg-clip-padding text-sm font-medium whitespace-nowrap',
    'transition-all outline-none select-none',
    'cursor-pointer',
    'data-[slot=help-trigger]:rounded-full data-[slot=help-trigger]:text-muted-foreground data-[slot=help-trigger]:shadow-none data-[slot=help-trigger]:hover:text-foreground',
    'disabled:pointer-events-none disabled:cursor-not-allowed',
    'disabled:opacity-50',
    'focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50',
    'aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20',
    'dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40',
    'selection:bg-selected selection:text-selected-foreground',
    'active:not-aria-[haspopup]:translate-y-px',
    '[&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*="size-"])]:size-4',
  ],
  {
    defaultVariants: {
      size: 'md',
      variant: 'primary',
    },
    variants: {
      size: {
        default: 'h-8 gap-1.5 px-2.5 has-[>svg]:px-2 [&_svg]:size-4',
        rail: 'h-auto w-4 rounded-none p-0',
        icon: 'size-8 [&_svg]:size-4',
        'icon-lg': 'size-9 [&_svg]:size-4',
        'icon-sm': 'size-7 [&_svg]:size-3.5',
        'icon-xs': 'size-6 [&_svg:not([class*="size-"])]:size-3',
        lg: 'h-9 gap-1.5 px-2.5 has-[>svg]:px-2 [&_svg]:size-4',
        md: 'h-8 gap-1.5 px-2.5 has-[>svg]:px-2 [&_svg]:size-4',
        sm: 'h-7 gap-1 px-2.5 text-xs has-[>svg]:px-2 [&_svg]:size-3.5',
        xs: 'h-6 gap-1 px-2 text-xs has-[>svg]:px-1.5 [&_svg]:size-3',
      },
      variant: {
        default: 'bg-primary text-primary-foreground shadow-xs hover:bg-primary/90 active:bg-primary/80',
        rail: 'rounded-none border-0 bg-transparent shadow-none transition-none hover:bg-transparent hover:after:bg-sidebar-border',
        calendar:
          'flex aspect-square size-auto w-full min-w-(--cell-size) flex-col gap-1 bg-transparent leading-none font-normal text-foreground group-data-[focused=true]/day:relative group-data-[focused=true]/day:z-10 group-data-[focused=true]/day:border-selected group-data-[focused=true]/day:ring-3 group-data-[focused=true]/day:ring-selected/50 hover:bg-muted hover:text-foreground active:bg-muted/80 data-[range-end=true]:rounded-md data-[range-end=true]:rounded-r-md data-[range-end=true]:bg-selected data-[range-end=true]:text-selected-foreground data-[range-middle=true]:rounded-none data-[range-middle=true]:bg-accent data-[range-middle=true]:text-accent-foreground data-[range-start=true]:rounded-md data-[range-start=true]:rounded-l-md data-[range-start=true]:bg-selected data-[range-start=true]:text-selected-foreground data-[selected-single=true]:bg-selected data-[selected-single=true]:text-selected-foreground dark:hover:text-accent-foreground [&>span]:text-xs [&>span]:opacity-70',
        accent: [
          'bg-primary text-primary-foreground shadow-xs',
          'hover:bg-primary/90',
          'active:bg-primary/80',
          'disabled:bg-muted disabled:text-muted-foreground',
        ],
        'accent-ghost': [
          'bg-transparent text-primary',
          'hover:bg-primary/10 hover:text-primary',
          'active:bg-primary/15',
          'disabled:text-muted-foreground',
        ],
        'accent-outline': [
          'border !border-primary bg-transparent text-primary shadow-xs',
          'hover:border-primary/80 hover:bg-primary/10',
          'active:border-primary/70 active:bg-primary/15',
          'disabled:border-border disabled:text-muted-foreground',
        ],
        dashed: [
          'border-2 border-dashed !border-primary bg-transparent text-primary',
          'hover:border-primary/80 hover:bg-primary/5',
          'active:bg-primary/10',
          'disabled:border-border disabled:text-muted-foreground',
        ],
        destructive: [
          'bg-destructive text-primary-foreground shadow-xs',
          'hover:bg-destructive/90',
          'active:bg-destructive/80',
          'focus-visible:ring-destructive',
          'disabled:bg-muted disabled:text-muted-foreground',
        ],
        'destructive-ghost': [
          'bg-transparent text-destructive',
          'hover:bg-destructive/10 hover:text-destructive',
          'active:bg-destructive/10',
          'focus-visible:ring-destructive',
          'disabled:text-muted-foreground',
        ],
        'destructive-outline': [
          'border !border-destructive bg-transparent text-destructive shadow-xs',
          'hover:border-destructive/80 hover:bg-destructive/10',
          'active:border-destructive/70 active:bg-destructive/15',
          'focus-visible:ring-destructive',
          'disabled:border-border disabled:text-muted-foreground',
        ],
        ghost: ['bg-transparent text-foreground', 'hover:bg-muted hover:text-foreground', 'active:bg-muted/80'],
        inverse: [
          'bg-foreground text-background shadow-xs',
          'hover:bg-foreground/90',
          'active:bg-foreground/80',
          'disabled:bg-muted disabled:text-muted-foreground',
        ],
        'inverse-ghost': [
          'bg-transparent text-primary-foreground',
          'hover:bg-primary-foreground/10',
          'active:bg-primary-foreground/15',
          'disabled:text-muted-foreground',
        ],
        'inverse-outline': [
          'border !border-primary-foreground bg-transparent text-primary-foreground shadow-xs',
          'hover:border-transparent hover:bg-primary-foreground/10',
          'active:border-transparent active:bg-primary-foreground/15',
          'disabled:border-muted-foreground disabled:text-muted-foreground',
        ],
        link: [
          'text-primary underline-offset-4',
          'hover:text-primary/80 hover:underline',
          'active:text-primary/60',
          'disabled:text-muted-foreground disabled:no-underline',
        ],
        outline: [
          'border border-input bg-background text-foreground shadow-xs',
          'hover:bg-muted hover:text-foreground',
          'active:bg-muted/80',
        ],
        primary: [
          'bg-primary text-primary-foreground shadow-xs',
          'hover:bg-primary/90',
          'active:bg-primary/80',
          undefined,
        ],
        secondary: [
          'bg-primary text-primary-foreground shadow-xs',
          'hover:bg-primary/90',
          'active:bg-primary/80',
          'disabled:bg-muted disabled:text-muted-foreground',
        ],
        'secondary-ghost': [
          'bg-transparent text-secondary-foreground',
          'hover:bg-secondary',
          'active:bg-secondary/80',
          'disabled:text-muted-foreground',
        ],
        'secondary-outline': [
          'border !border-primary-foreground text-secondary-foreground shadow-xs',
          'hover:border-ring hover:bg-secondary/50',
          'active:border-ring active:bg-secondary/80',
          'disabled:border-border disabled:text-muted-foreground',
        ],
      },
    },
  }
);

export type ButtonVariants = VariantProps<typeof buttonVariants>;

export type ButtonProps = ButtonPrimitive.Props &
  ButtonVariants & {
    asChild?: boolean | undefined;
    as?: ElementType | undefined;
    to?: string | undefined;
    icon?: React.ReactNode | undefined;
    isLoading?: boolean | undefined;
    href?: string | undefined;
    target?: string | undefined;
    rel?: string | undefined;
  } & SharedProps;

function ButtonContent({ children, icon, isLoading }: Pick<ButtonProps, 'children' | 'icon' | 'isLoading'>) {
  const content = icon ? (
    <>
      {children}
      {icon}
    </>
  ) : (
    children
  );
  if (isLoading === true) {
    return (
      <>
        <span className="invisible contents">{content}</span>
        <span aria-hidden="true" className="absolute inset-0 flex items-center justify-center">
          <Spinner />
        </span>
      </>
    );
  }
  return content;
}

type ButtonStyleProps = Pick<ButtonProps, 'className' | 'variant' | 'size' | 'icon' | 'isLoading'> & {
  positionClasses: string;
};

function getButtonClasses(
  { className, variant, size, icon, isLoading, positionClasses }: ButtonStyleProps,
  state: ButtonPrimitive.State
) {
  return cn(
    buttonVariants({ size, variant }),
    positionClasses,
    icon && 'gap-2',
    isLoading === true && 'relative',
    typeof className === 'function' ? className(state) : className
  );
}

function getButtonPositionClasses(attached: boolean, position: ReturnType<typeof useGroup>['position']) {
  if (!attached) {
    return 'rounded-lg';
  }
  if (position === 'first') {
    return 'rounded-r-none rounded-l-lg border-r-0';
  }
  if (position === 'last') {
    return 'rounded-r-lg rounded-l-none border-l-0';
  }
  if (position === 'middle') {
    return 'rounded-none border-r-0 border-l-0';
  }
  return 'rounded-lg';
}

function LegacyButton({
  as,
  asChild,
  children,
  className,
  variant,
  size,
  icon,
  isLoading,
  positionClasses,
  disabled,
  style,
  focusableWhenDisabled: _focusableWhenDisabled,
  ...props
}: ButtonProps & { positionClasses: string }) {
  const Component = as ?? Slot;
  const state: ButtonPrimitive.State = { disabled: disabled === true };
  return React.createElement(
    Component,
    {
      ...props,
      className: getButtonClasses({ className, variant, size, icon, isLoading, positionClasses }, state),
      disabled,
      style: typeof style === 'function' ? style(state) : style,
    },
    asChild === true ? (
      children
    ) : (
      <ButtonContent icon={icon} isLoading={isLoading}>
        {children}
      </ButtonContent>
    )
  );
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      className,
      variant,
      size,
      asChild = false,
      testId,
      as,
      to,
      icon,
      isLoading = false,
      disabled,
      children,
      render,
      nativeButton,
      type = 'button',
      ...props
    },
    ref
  ) => {
    const { attached, position } = useGroup();
    const isDisabled = disabled === true || isLoading;
    const positionClasses = getButtonPositionClasses(attached, position);
    const shared = {
      'aria-busy': isLoading === true ? true : undefined,
      'data-loading': isLoading === true ? true : undefined,
      'data-slot': 'button',
      'data-testid': testId,
      disabled: isDisabled,
      ref,
      type,
    } as const;
    const styleProps = { className, variant, size, icon, isLoading, positionClasses };
    if (asChild === true || as !== undefined) {
      return (
        <LegacyButton {...shared} {...props} {...styleProps} as={as} asChild={asChild} to={to}>
          {children}
        </LegacyButton>
      );
    }
    return (
      <ButtonPrimitive
        {...shared}
        {...props}
        className={(state) => getButtonClasses(styleProps, state)}
        nativeButton={nativeButton}
        render={render}
      >
        <ButtonContent icon={icon} isLoading={isLoading}>
          {children}
        </ButtonContent>
      </ButtonPrimitive>
    );
  }
);

Button.displayName = 'Button';

export { Button, buttonVariants };

'use client';

import { Checkbox as CheckboxPrimitive } from '@base-ui/react/checkbox';
import { cva, type VariantProps } from 'class-variance-authority';
import { type HTMLMotionProps, motion } from 'motion/react';
import type React from 'react';
import { useState } from 'react';

import { splitMotionProps } from '@/registry/base-nova/protoform/lib/base-ui-compat';
import { cn, type SharedProps } from '@/registry/base-nova/protoform/lib/utils';

const pathDrawClassName =
  '[stroke-dasharray:1] [stroke-dashoffset:1] opacity-0 transition-[stroke-dashoffset,opacity] duration-200 ease-out data-[visible=true]:[stroke-dashoffset:0] data-[visible=true]:opacity-100 data-[visible=true]:delay-100';

const checkboxVariants = cva(
  'peer relative flex size-4 shrink-0 cursor-pointer items-center justify-center rounded-sm border transition-colors outline-none after:absolute after:-inset-x-3 after:-inset-y-2 focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 motion-safe:hover:scale-105 motion-safe:active:scale-95 dark:bg-input/30 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40',
  {
    defaultVariants: {
      variant: 'primary',
    },
    variants: {
      variant: {
        outline:
          '!border-input data-[state=checked]:border-foreground data-[state=checked]:bg-transparent data-[state=checked]:text-foreground data-[state=indeterminate]:border-foreground data-[state=indeterminate]:bg-transparent data-[state=indeterminate]:text-foreground',
        primary:
          '!border-input data-[state=checked]:border-primary data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground data-[state=indeterminate]:border-primary data-[state=indeterminate]:bg-primary data-[state=indeterminate]:text-primary-foreground',
        secondary:
          '!border-input data-[state=checked]:border-secondary data-[state=checked]:bg-secondary data-[state=checked]:text-primary-foreground data-[state=indeterminate]:border-secondary data-[state=indeterminate]:bg-secondary data-[state=indeterminate]:text-primary-foreground',
      },
    },
  }
);

type PrimitiveCheckboxProps = React.ComponentProps<typeof CheckboxPrimitive.Root>;
type CheckboxProps = Omit<PrimitiveCheckboxProps, 'checked' | 'defaultChecked'> &
  Omit<HTMLMotionProps<'button'>, keyof PrimitiveCheckboxProps> &
  VariantProps<typeof checkboxVariants> &
  SharedProps & {
    checked?: boolean | 'indeterminate' | undefined;
    defaultChecked?: boolean | 'indeterminate' | undefined;
  };

function Checkbox({
  className,
  variant,
  testId,
  checked,
  defaultChecked,
  indeterminate,
  onCheckedChange,
  nativeButton,
  render,
  children,
  ...props
}: CheckboxProps) {
  const [uncontrolledIndeterminate, setUncontrolledIndeterminate] = useState(defaultChecked === 'indeterminate');
  const handleCheckedChange: NonNullable<PrimitiveCheckboxProps['onCheckedChange']> = (next, details) => {
    onCheckedChange?.(next, details);
    if (!details.isCanceled && checked === undefined) {
      setUncontrolledIndeterminate(false);
    }
  };
  const separated = splitMotionProps(props);
  const renderRoot: NonNullable<PrimitiveCheckboxProps['render']> = (rootProps, state) => {
    const Root: React.ElementType = nativeButton === false ? 'span' : 'button';
    let dataState = 'unchecked';
    if (state.checked) {
      dataState = 'checked';
    }
    if (state.indeterminate) {
      dataState = 'indeterminate';
    }
    return <Root {...rootProps} data-state={dataState} />;
  };
  return (
    <CheckboxPrimitive.Root
      {...separated.native}
      checked={checked === 'indeterminate' ? false : checked}
      className={(state) =>
        cn(checkboxVariants({ variant }), typeof className === 'function' ? className(state) : className)
      }
      data-slot="checkbox"
      data-testid={testId}
      defaultChecked={defaultChecked === 'indeterminate' ? false : defaultChecked}
      indeterminate={
        indeterminate ?? (checked === 'indeterminate' || (checked === undefined && uncontrolledIndeterminate))
      }
      nativeButton={nativeButton ?? render === undefined}
      onCheckedChange={handleCheckedChange}
      render={render ?? renderRoot}
    >
      <motion.span className="contents" {...separated.motion}>
        {children}
        <CheckboxPrimitive.Indicator className="group/indicator size-3.5" keepMounted render={<span />}>
          <svg
            aria-hidden="true"
            className="size-3.5"
            data-slot="checkbox-indicator"
            fill="none"
            stroke="currentColor"
            strokeWidth="3.5"
            viewBox="0 0 24 24"
          >
            <path
              className={cn(
                pathDrawClassName,
                'group-data-checked/indicator:opacity-100 group-data-checked/indicator:[stroke-dashoffset:0] group-data-indeterminate/indicator:hidden'
              )}
              d="M4.5 12.75l6 6 9-13.5"
              pathLength={1}
              strokeLinecap="round"
              strokeLinejoin="round"
            />
            <path
              className={cn(
                pathDrawClassName,
                'group-data-indeterminate/indicator:opacity-100 group-data-indeterminate/indicator:[stroke-dashoffset:0]'
              )}
              d="M5 12h14"
              pathLength={1}
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </CheckboxPrimitive.Indicator>
      </motion.span>
    </CheckboxPrimitive.Root>
  );
}

export { Checkbox, type CheckboxProps, checkboxVariants };

'use client';

import { Menu as MenuPrimitive } from '@base-ui/react/menu';
import { CheckIcon, ChevronRightIcon } from 'lucide-react';
import type React from 'react';
import { usePortalContainer } from '@/registry/base-nova/protoform/hooks/use-portal-container';
import { cn } from '@/registry/base-nova/protoform/lib/utils';

function DropdownMenu({ ...props }: MenuPrimitive.Root.Props) {
  return <MenuPrimitive.Root data-slot="dropdown-menu" {...props} />;
}
function DropdownMenuPortal({ container, ...props }: MenuPrimitive.Portal.Props) {
  const portalContainer = usePortalContainer();
  return <MenuPrimitive.Portal container={container ?? portalContainer} data-slot="dropdown-menu-portal" {...props} />;
}
function DropdownMenuTrigger({ ...props }: MenuPrimitive.Trigger.Props) {
  return <MenuPrimitive.Trigger data-slot="dropdown-menu-trigger" {...props} />;
}
function DropdownMenuContent({
  align = 'start',
  alignOffset = 0,
  side = 'bottom',
  sideOffset = 4,
  variant,
  className,
  ...props
}: MenuPrimitive.Popup.Props &
  Pick<MenuPrimitive.Positioner.Props, 'align' | 'alignOffset' | 'side' | 'sideOffset'> & {
    variant?: 'submenu' | 'menubar' | 'menubar-submenu';
  }) {
  return (
    <DropdownMenuPortal>
      <MenuPrimitive.Positioner
        align={align}
        alignOffset={alignOffset}
        className="isolate z-50 outline-none"
        side={side}
        sideOffset={sideOffset}
      >
        <MenuPrimitive.Popup
          className={(state) =>
            cn(
              'z-50 max-h-(--available-height) w-(--anchor-width) min-w-32 origin-(--transform-origin) overflow-x-hidden overflow-y-auto rounded-lg bg-popover p-1 text-popover-foreground shadow-md ring-1 ring-foreground/10 duration-100 outline-none data-closed:animate-out data-closed:overflow-hidden data-closed:fade-out-0 data-closed:zoom-out-95 data-open:animate-in data-open:fade-in-0 data-open:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=inline-end]:slide-in-from-left-2 data-[side=inline-start]:slide-in-from-right-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2',
              variant === 'submenu' && 'w-auto min-w-24',
              variant === 'menubar' && 'min-w-36',
              variant === 'menubar-submenu' && 'w-auto min-w-32',
              typeof className === 'function' ? className(state) : className
            )
          }
          data-slot="dropdown-menu-content"
          {...props}
        />
      </MenuPrimitive.Positioner>
    </DropdownMenuPortal>
  );
}
function DropdownMenuGroup({ ...props }: MenuPrimitive.Group.Props) {
  return <MenuPrimitive.Group data-slot="dropdown-menu-group" {...props} />;
}
function DropdownMenuLabel({
  className,
  inset,
  ...props
}: MenuPrimitive.GroupLabel.Props & {
  inset?: boolean;
}) {
  return (
    <MenuPrimitive.GroupLabel
      className={(state) =>
        cn(
          'px-1.5 py-1 text-xs font-medium text-muted-foreground data-inset:pl-7',
          typeof className === 'function' ? className(state) : className
        )
      }
      data-inset={inset}
      data-slot="dropdown-menu-label"
      {...props}
    />
  );
}
function DropdownMenuItem({
  className,
  inset,
  variant = 'default',
  ...props
}: MenuPrimitive.Item.Props & {
  inset?: boolean;
  variant?: 'default' | 'destructive';
}) {
  return (
    <MenuPrimitive.Item
      className={(state) =>
        cn(
          "group/dropdown-menu-item relative flex cursor-default items-center gap-1.5 rounded-md px-1.5 py-1 text-sm outline-hidden select-none focus:bg-accent focus:text-accent-foreground not-data-[variant=destructive]:focus:**:text-accent-foreground data-disabled:pointer-events-none data-disabled:opacity-50 data-inset:pl-7 data-[variant=destructive]:text-destructive data-[variant=destructive]:focus:bg-destructive/10 data-[variant=destructive]:focus:text-destructive dark:data-[variant=destructive]:focus:bg-destructive/20 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4 data-[variant=destructive]:*:[svg]:text-destructive",
          typeof className === 'function' ? className(state) : className
        )
      }
      data-inset={inset}
      data-slot="dropdown-menu-item"
      data-variant={variant}
      {...props}
    />
  );
}
function DropdownMenuSub({ ...props }: MenuPrimitive.SubmenuRoot.Props) {
  return <MenuPrimitive.SubmenuRoot data-slot="dropdown-menu-sub" {...props} />;
}
function DropdownMenuSubTrigger({
  className,
  inset,
  children,
  ...props
}: MenuPrimitive.SubmenuTrigger.Props & {
  inset?: boolean;
}) {
  return (
    <MenuPrimitive.SubmenuTrigger
      className={(state) =>
        cn(
          "flex cursor-default items-center gap-1.5 rounded-md px-1.5 py-1 text-sm outline-hidden select-none focus:bg-accent focus:text-accent-foreground not-data-[variant=destructive]:focus:**:text-accent-foreground data-inset:pl-7 data-open:bg-accent data-open:text-accent-foreground data-popup-open:bg-accent data-popup-open:text-accent-foreground [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
          typeof className === 'function' ? className(state) : className
        )
      }
      data-inset={inset}
      data-slot="dropdown-menu-sub-trigger"
      {...props}
    >
      {children}
      <ChevronRightIcon className="ml-auto rtl:-scale-x-100" />
    </MenuPrimitive.SubmenuTrigger>
  );
}
function DropdownMenuSubContent({
  align = 'start',
  alignOffset = -3,
  side = 'right',
  sideOffset = 0,
  className,
  ...props
}: React.ComponentProps<typeof DropdownMenuContent>) {
  return (
    <DropdownMenuContent
      align={align}
      alignOffset={alignOffset}
      className={className}
      data-slot="dropdown-menu-sub-content"
      side={side}
      sideOffset={sideOffset}
      variant="submenu"
      {...props}
    />
  );
}
function DropdownMenuCheckboxItem({
  className,
  children,
  checked,
  inset,
  ...props
}: MenuPrimitive.CheckboxItem.Props & {
  inset?: boolean;
}) {
  return (
    <MenuPrimitive.CheckboxItem
      checked={checked}
      className={(state) =>
        cn(
          "relative flex cursor-default items-center gap-1.5 rounded-md py-1 pr-8 pl-1.5 text-sm outline-hidden select-none focus:bg-accent focus:text-accent-foreground focus:**:text-accent-foreground data-disabled:pointer-events-none data-disabled:opacity-50 data-inset:pl-7 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
          typeof className === 'function' ? className(state) : className
        )
      }
      data-inset={inset}
      data-slot="dropdown-menu-checkbox-item"
      {...props}
    >
      <span
        className="pointer-events-none absolute right-2 flex items-center justify-center"
        data-slot="dropdown-menu-checkbox-item-indicator"
      >
        <MenuPrimitive.CheckboxItemIndicator>
          <CheckIcon />
        </MenuPrimitive.CheckboxItemIndicator>
      </span>
      {children}
    </MenuPrimitive.CheckboxItem>
  );
